content.text:
Read file capture.sh, lines 1-66
1: #!/usr/bin/env bash
2: # Capture desktop + mobile screenshots of the running app.
3: # Env: CAPTURE_URL (exact URL to open), CAPTURE_DIR (output dir, outside source).
4: # Writes final-desktop.png and final-mobile.png, leaves the app running.
5: # Exit 75 = temporary navigation/browser infrastructure failure; exit 1 = script/rendering defect.
6: # Per-command timing via /usr/bin/time -p (stderr only).
7: set -euo pipefail
8: cd "$(dirname "$0")"
9: 
10: /usr/bin/time -p test -n "${CAPTURE_URL:-}" || { echo "Set CAPTURE_URL." >&2; exit 1; }
11: /usr/bin/time -p test -n "${CAPTURE_DIR:-}" || { echo "Set CAPTURE_DIR." >&2; exit 1; }
12: case "$CAPTURE_URL" in
13:   http://*|https://*) ;;
14:   *) echo "CAPTURE_URL must start with http:// or https://." >&2; exit 1 ;;
15: esac
16: /usr/bin/time -p mkdir -p "$CAPTURE_DIR"
17: 
18: /usr/bin/time -p node -e '
19: const { mkdirSync } = require("node:fs");
20: const { join } = require("node:path");
21: const { createRequire } = require("node:module");
22: const url = process.env.CAPTURE_URL, output = process.env.CAPTURE_DIR;
23: if (!url || !output) { console.error("Set CAPTURE_URL and CAPTURE_DIR."); process.exit(1); }
24: mkdirSync(output, { recursive: true });
25: const runtime = join(process.env.HOME, ".local/share/omgithub-playwright");
26: const require2 = createRequire(join(runtime, "package.json"));
27: const { chromium } = require2("playwright");
28: const config = require("node:fs").readFileSync(join(runtime, process.platform === "darwin" ? "metal.json" : "linux.json"), "utf8");
29: const launchOptions = JSON.parse(config).browser.launchOptions;
30: if (process.platform === "linux") process.env.DISPLAY ||= ":" + require("node:fs").readFileSync(join(runtime, "display"), "utf8").trim();
31: const transient = (error) => { throw Object.assign(error instanceof Error ? error : new Error(String(error)), { exitCode: 75 }); };
32: (async () => {
33:   let browser;
34:   try {
35:     browser = await chromium.launch({ ...launchOptions, timeout: 30000 }).catch(transient);
36:     for (const [name, width, height] of [["desktop", 1440, 900], ["mobile", 390, 844]]) {
37:       const page = await browser.newPage({ viewport: { width, height } }).catch(transient);
38:       page.setDefaultTimeout(30000);
39:       page.on("pageerror", (error) => console.error(error.message));
40:       const response = await page.goto(url, { waitUntil: "load", timeout: 45000 }).catch(transient);
41:       if (!response?.ok()) throw Object.assign(new Error("HTTP " + response?.status() + " loading preview"), { exitCode: !response || [408, 429, 500, 502, 503, 504].includes(response.status()) ? 75 : 1 });
42:       await page.locator("body").waitFor({ state: "visible" });
43:       await page.waitForFunction(() => document.fonts.status === "loaded");
44:       await page.waitForTimeout(1500);
45:       await page.screenshot({ path: join(output, "final-" + name + ".png"), timeout: 30000 }).catch((error) => {
46:         if (error.name === "TimeoutError" || !browser.isConnected()) transient(error);
47:         throw error;
48:       });
49:       await page.close();
50:     }
51:   } catch (error) { console.error(error && error.message ? error.message : error); process.exitCode = error.exitCode || 1; }
52:   finally { await browser?.close().catch((error) => { console.error(error && error.message ? error.message : error); process.exitCode ||= 75; }); }
53: })();
54: '
55: 
56: /usr/bin/time -p test -f "$CAPTURE_DIR/final-desktop.png" || { echo "Missing final-desktop.png." >&2; exit 1; }
57: /usr/bin/time -p test -f "$CAPTURE_DIR/final-mobile.png" || { echo "Missing final-mobile.png." >&2; exit 1; }
58: /usr/bin/time -p node -e '
59: const fs = require("node:fs");
